// Fails if any image or audio file ships with the game: every pixel and sound is generated by code.
import { readdirSync, statSync } from 'fs'
import { join, relative } from 'path'

const ROOT = join(import.meta.dir, '..')
const BANNED = /\.(png|jpe?g|gif|webp|bmp|ico|svg|tga|ktx2?|dds|mp3|ogg|wav|flac|aac|m4a|opus)$/i
const SKIP = new Set(['node_modules', 'media', '.git'])
const bad: string[] = []
const walk = (dir: string) => {
  for (const name of readdirSync(dir)) {
    if (SKIP.has(name)) continue
    const p = join(dir, name)
    if (statSync(p).isDirectory()) walk(p)
    else if (BANNED.test(name)) bad.push(relative(ROOT, p))
  }
}
walk(ROOT)
if (bad.length) { console.error(`asset check FAILED: ${bad.length} image/audio file(s):\n  ${bad.join('\n  ')}`); process.exit(1) }
console.log('asset check passed: 0 image/audio files (media/ holds the demo video only)')
